<script setup lang="ts">
const supabase=useSupabaseClient();const rows=ref<any[]>([]);const show=ref(false);const editId=ref<string|null>(null);const form=reactive<any>({vlan_id:null,vlan_name:'',purpose:'',network_subnet:'',dhcp_scope:'',tagged_untagged:'',notes:''});async function load(){const {data}=await supabase.from('vlans').select('*').order('vlan_id');rows.value=data||[]}function add(){editId.value=null;Object.assign(form,{vlan_id:null,vlan_name:'',purpose:'',network_subnet:'',dhcp_scope:'',tagged_untagged:'',notes:''});show.value=true}function edit(r:any){editId.value=r.id;Object.assign(form,r);show.value=true}async function save(){const payload={...form,network_subnet:form.network_subnet||null};editId.value?await supabase.from('vlans').update(payload).eq('id',editId.value):await supabase.from('vlans').insert(payload);show.value=false;await load()}async function del(r:any){if(confirm(`Delete VLAN ${r.vlan_id}?`)){await supabase.from('vlans').delete().eq('id',r.id);await load()}}onMounted(load)
</script><template><section><div class="pagehead"><div><h2>VLAN Reference</h2><p>Reference VLAN IDs, subnets and purpose while mapping ports.</p></div><button class="btn" @click="add">+ Add VLAN</button></div><div class="tablewrap"><table><thead><tr><th>ID</th><th>Name</th><th>Purpose</th><th>Subnet</th><th>DHCP Scope</th><th>Tagging</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.vlan_id}}</strong></td><td>{{r.vlan_name}}</td><td>{{r.purpose||'—'}}</td><td>{{r.network_subnet||'—'}}</td><td>{{r.dhcp_scope||'—'}}</td><td>{{r.tagged_untagged||'—'}}</td><td><button class="link" @click="edit(r)">Edit</button> <button class="link danger" @click="del(r)">Delete</button></td></tr></tbody></table></div><AppModal v-if="show" title="VLAN" @close="show=false"><form class="formgrid" @submit.prevent="save"><label>VLAN ID<input v-model.number="form.vlan_id" type="number" required></label><label>Name<input v-model="form.vlan_name" required></label><label>Purpose<input v-model="form.purpose"></label><label>Network / Subnet<input v-model="form.network_subnet" placeholder="10.0.0.0/24"></label><label>DHCP Scope<input v-model="form.dhcp_scope"></label><label>Tagged / Untagged<input v-model="form.tagged_untagged"></label><label class="full">Notes<textarea v-model="form.notes"></textarea></label><div class="full right"><button class="btn secondary" type="button" @click="show=false">Cancel</button> <button class="btn">Save</button></div></form></AppModal></section></template>
